#include <string>
#include <vector>

std::string utf8(char32_t c)
{
    if ((c >= 0xD800 && c <= 0xDFFF) || c > 0x10FFFF) c = 0xFFFD;
    std::string out;
    if (c < 0x80) out += static_cast<char>(c);
    else if (c < 0x800)
    {
        out += static_cast<char>(0xC0 | (c >> 6));
        out += static_cast<char>(0x80 | (c & 0x3F));
    }
    else if (c < 0x10000)
    {
        out += static_cast<char>(0xE0 | (c >> 12));
        out += static_cast<char>(0x80 | ((c >> 6) & 0x3F));
        out += static_cast<char>(0x80 | (c & 0x3F));
    }
    else
    {
        out += static_cast<char>(0xF0 | (c >> 18));
        out += static_cast<char>(0x80 | ((c >> 12) & 0x3F));
        out += static_cast<char>(0x80 | ((c >> 6) & 0x3F));
        out += static_cast<char>(0x80 | (c & 0x3F));
    }
    return out;
}

std::vector<char32_t> decodeUtf8(const std::string& text)
{
    std::vector<char32_t> out;
    std::size_t i{ 0 };
    while (i < text.size())
    {
        const unsigned char b{ static_cast<unsigned char>(text[i]) };
        int extra{ -1 };
        char32_t c{ 0 };
        if (b < 0x80) { extra = 0; c = b; }
        else if ((b & 0xE0) == 0xC0) { extra = 1; c = b & 0x1F; }
        else if ((b & 0xF0) == 0xE0) { extra = 2; c = b & 0x0F; }
        else if ((b & 0xF8) == 0xF0) { extra = 3; c = b & 0x07; }
        bool ok{ extra >= 0 && i + static_cast<std::size_t>(extra) < text.size() + (extra == 0 ? 1 : 0) };
        if (ok && extra > 0 && i + static_cast<std::size_t>(extra) >= text.size()) ok = false;
        for (int k{ 1 }; ok && k <= extra; ++k)
        {
            const unsigned char n{ static_cast<unsigned char>(text[i + static_cast<std::size_t>(k)]) };
            if ((n & 0xC0) != 0x80) ok = false;
            else c = (c << 6) | (n & 0x3F);
        }
        if (!ok) { out.push_back(0xFFFD); ++i; continue; }
        out.push_back(c);
        i += static_cast<std::size_t>(extra) + 1;
    }
    return out;
}

unitTests:
TEST("ASCII") { CHECK_EQ(utf8(U'A'), std::string("A")); CHECK_EQ(utf8(0), std::string(1, '\0')); }
TEST("two bytes") { CHECK_EQ(utf8(0xE9), std::string("\xC3\xA9")); }
TEST("three bytes: an icon") { CHECK_EQ(utf8(0xF0C7), std::string("\xEF\x83\x87")); CHECK_EQ(utf8(0x20AC), std::string("\xE2\x82\xAC")); }
TEST("four bytes") { CHECK_EQ(utf8(0x1F600), std::string("\xF0\x9F\x98\x80")); }
TEST("invalid becomes U+FFFD") { CHECK_EQ(utf8(0xD800), std::string("\xEF\xBF\xBD")); CHECK_EQ(utf8(0x110000), std::string("\xEF\xBF\xBD")); }
TEST("decode") { CHECK_EQ(decodeUtf8("A\xC3\xA9\xEF\x83\x87\xF0\x9F\x98\x80"), (std::vector<char32_t>{ U'A', 0xE9, 0xF0C7, 0x1F600 })); }
TEST("decode bad bytes") { CHECK_EQ(decodeUtf8("\x80" "A"), (std::vector<char32_t>{ 0xFFFD, U'A' })); CHECK_EQ(decodeUtf8("\xE2\x82"), (std::vector<char32_t>{ 0xFFFD, 0xFFFD })); }
TEST("round trip") { std::string s; for (char32_t c : { char32_t(0x41), char32_t(0x3A9), char32_t(0xE000), char32_t(0x10FFFF) }) s += utf8(c); CHECK_EQ(decodeUtf8(s), (std::vector<char32_t>{ 0x41, 0x3A9, 0xE000, 0x10FFFF })); }

